document.addEventListener("DOMContentLoaded", function () {
const container = document.getElementById('ws-walkscore-tile');
if (!container) return;

const ws_wsid = 'gde15fdb81d974ecf93764f6d0a93d8e8'; // senin WSID
const address = container.dataset.address || '';
const zipcode = container.dataset.zipcode || '';
const lat = container.dataset.lat || '';
const lon = container.dataset.lon || '';
const ws_address = `${address} ${zipcode}`.trim();
const ws_format = 'tall';
const ws_width = '100%';
const ws_height = '500';

const style = document.createElement('style');
style.type = 'text/css';
style.textContent = `
#ws-walkscore-tile { position:relative; text-align:left; }
#ws-walkscore-tile * { float:none; }
`;
document.head.appendChild(style);

const scriptVars = document.createElement('script');
scriptVars.type = 'text/javascript';
scriptVars.text = `
var ws_wsid = '${ws_wsid}';
var ws_address = '${ws_address}';
var ws_lat = '${lat}';
var ws_lon = '${lon}';
var ws_format = '${ws_format}';
var ws_width = '${ws_width}';
var ws_height = '${ws_height}';
`;
document.body.appendChild(scriptVars);

const scriptSrc = document.createElement('script');
scriptSrc.type = 'text/javascript';
scriptSrc.src = 'https://www.walkscore.com/tile/show-walkscore-tile.php';
document.body.appendChild(scriptSrc);
});

        // 
    document.addEventListener("DOMContentLoaded", function () {
        var container = document.getElementById('gsWidget');
        if (!container) return;

        var options = {
            cityName: encodeURIComponent(container.dataset.cityname || ''),
            state: container.dataset.state || '',
            zipcode: container.dataset.zipcode || '',
            lat: container.dataset.latitude || '',
            lon: container.dataset.longitude || '',
            width: container.offsetWidth,
            height: Math.max(434, Math.min(600, Math.round(container.offsetWidth / 1.78))),
            textColor: '0066B8',
            bordersColor: 'ffcc66',
            zoom: 12
        };

        var iframeSrc = window.location.protocol + '//www.greatschools.org/widget/map?searchQuery=' + options.zipcode;

        var queryParams = Object.keys(options)
            .filter(function(key) { return key !== 'zipcode'; })
            .map(function(key) { return key + '=' + options[key]; })
            .join('&');

        iframeSrc += '&' + queryParams;

        var iframe = document.createElement('iframe');
        iframe.className = 'greatschools';
        iframe.src = iframeSrc;
        iframe.width = options.width;
        iframe.height = options.height;
        iframe.marginHeight = 0;
        iframe.marginWidth = 0;
        iframe.scrolling = 'no';
        iframe.frameBorder = 0;

        container.innerHTML = '';
        container.appendChild(iframe);
    });
//
